package burp.curl;

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.io.UncheckedIOException;
import java.nio.charset.StandardCharsets;
import java.util.ArrayList;
import java.util.Collection;
import java.util.Collections;
import java.util.HashMap;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.Optional;

/**
 * Lookup table of every curl command-line option, loaded from {@code curl-options.tsv}
 * (generated by {@code tools/gen-curl-options.py}).
 */
public final class CurlOptionTable {

    /**
     * Result of resolving the text after a leading {@code --}.
     * @param spec the option
     * @param negated true when written as {@code --no-<name>}
     * @param expand true when written as {@code --expand-<name>}
     * @param inlineValue value of the tolerant {@code name=value} form, otherwise null
     */
    public record LongMatch(OptionSpec spec, boolean negated, boolean expand, String inlineValue) {
    }

    private static final String RESOURCE = "/curl-options.tsv";
    private static final CurlOptionTable INSTANCE = load();

    private final Map<String, OptionSpec> byLong;
    private final Map<Character, OptionSpec> byShort;

    private CurlOptionTable(Map<String, OptionSpec> byLong, Map<Character, OptionSpec> byShort) {
        this.byLong = byLong;
        this.byShort = byShort;
    }

    /** @return the shared table */
    public static CurlOptionTable get() {
        return INSTANCE;
    }

    /** @return all options */
    public Collection<OptionSpec> all() {
        return Collections.unmodifiableCollection(byLong.values());
    }

    /**
     * @param name long name without leading dashes
     * @return the option with exactly that name
     */
    public Optional<OptionSpec> byLong(String name) {
        return Optional.ofNullable(name == null ? null : byLong.get(name));
    }

    /**
     * @param letter short option letter
     * @return the option with that letter
     */
    public Optional<OptionSpec> byShort(char letter) {
        return Optional.ofNullable(byShort.get(letter));
    }

    /**
     * Resolves what follows the leading {@code --}: exact name, {@code no-} negation,
     * {@code expand-} prefix, unique abbreviation, then tolerant {@code name=value}.
     * @param word the text after {@code --}
     * @return the match, or empty if unknown or ambiguous
     */
    public Optional<LongMatch> resolveLong(String word) {
        if (word == null || word.isEmpty()) {
            return Optional.empty();
        }
        Optional<LongMatch> m = resolveName(word);
        if (m.isPresent()) {
            return m;
        }
        int eq = word.indexOf('=');
        if (eq > 0) {
            Optional<LongMatch> base = resolveName(word.substring(0, eq));
            if (base.isPresent() && base.get().spec().takesArg()) {
                LongMatch b = base.get();
                return Optional.of(new LongMatch(b.spec(), b.negated(), b.expand(), word.substring(eq + 1)));
            }
        }
        return Optional.empty();
    }

    private Optional<LongMatch> resolveName(String word) {
        OptionSpec exact = byLong.get(word);
        if (exact != null) {
            return Optional.of(new LongMatch(exact, false, false, null));
        }
        if (word.startsWith("no-")) {
            String rest = word.substring(3);
            OptionSpec s = byLong.get(rest);
            if (s != null && s.negatable()) {
                return Optional.of(new LongMatch(s, true, false, null));
            }
        }
        if (word.startsWith("expand-")) {
            String rest = word.substring(7);
            OptionSpec s = byLong.get(rest);
            if (s != null && s.takesArg()) {
                return Optional.of(new LongMatch(s, false, true, null));
            }
        }
        OptionSpec p = uniquePrefix(word, false, false);
        if (p != null) {
            return Optional.of(new LongMatch(p, false, false, null));
        }
        if (word.startsWith("no-")) {
            OptionSpec s = uniquePrefix(word.substring(3), true, false);
            if (s != null) {
                return Optional.of(new LongMatch(s, true, false, null));
            }
        }
        if (word.startsWith("expand-")) {
            OptionSpec s = uniquePrefix(word.substring(7), false, true);
            if (s != null) {
                return Optional.of(new LongMatch(s, false, true, null));
            }
        }
        return Optional.empty();
    }

    private OptionSpec uniquePrefix(String prefix, boolean needNegatable, boolean needArg) {
        if (prefix.isEmpty()) {
            return null;
        }
        List<OptionSpec> hits = new ArrayList<>();
        for (OptionSpec s : byLong.values()) {
            if (!s.longName().startsWith(prefix)) {
                continue;
            }
            if ((needNegatable && !s.negatable()) || (needArg && !s.takesArg())) {
                continue;
            }
            hits.add(s);
        }
        if (hits.size() == 1) {
            return hits.get(0);
        }
        // several hits: the abbreviation is still unambiguous when one name is a prefix of all others
        // (e.g. "compr" -> "compressed", not "compressed-ssh")
        for (OptionSpec h : hits) {
            boolean all = true;
            for (OptionSpec o : hits) {
                if (!o.longName().startsWith(h.longName())) {
                    all = false;
                    break;
                }
            }
            if (all) {
                return h;
            }
        }
        return null;
    }

    private static CurlOptionTable load() {
        Map<String, OptionSpec> longs = new LinkedHashMap<>();
        Map<Character, OptionSpec> shorts = new HashMap<>();
        try (InputStream in = CurlOptionTable.class.getResourceAsStream(RESOURCE)) {
            if (in == null) {
                throw new IllegalStateException("missing resource " + RESOURCE);
            }
            BufferedReader r = new BufferedReader(new InputStreamReader(in, StandardCharsets.UTF_8));
            String line;
            while ((line = r.readLine()) != null) {
                if (line.isEmpty() || line.charAt(0) == '#') {
                    continue;
                }
                List<String> f = new ArrayList<>(List.of(line.split("\t", -1)));
                if (f.size() != 5) {
                    throw new IllegalStateException("bad line in " + RESOURCE + ": " + line);
                }
                char sh = f.get(1).isEmpty() ? 0 : f.get(1).charAt(0);
                OptionSpec spec = new OptionSpec(f.get(0), sh, ArgKind.valueOf(f.get(2)),
                        "1".equals(f.get(3)), Handling.valueOf(f.get(4)));
                if (longs.put(spec.longName(), spec) != null) {
                    throw new IllegalStateException("duplicate option " + spec.longName());
                }
                if (sh != 0 && shorts.put(sh, spec) != null) {
                    throw new IllegalStateException("duplicate short option " + sh);
                }
            }
        } catch (IOException e) {
            throw new UncheckedIOException(e);
        }
        return new CurlOptionTable(longs, shorts);
    }
}
